import { DOCUMENT } from '@angular/common';
import { Component, OnInit, inject, signal } from '@angular/core';
import { ActivatedRoute, Router, RouterLink } from '@angular/router';
import { HttpErrorResponse } from '@angular/common/http';
import { finalize } from 'rxjs';
import { AuthService } from './auth.service';

/** Extracts the unencoded URL fragment used by links generated by the backend. */
export function verificationTokenFromLocation(routeFragment: string | null, href: string): string | null {
  const browserFragment = href ? new URL(href).hash.slice(1) : '';
  const token = browserFragment || routeFragment || '';
  return token.length > 0 ? token : null;
}

@Component({
  selector: 'app-verify-email',
  standalone: true,
  imports: [RouterLink],
  template: '<main class="verification-page"><section class="surface-card verification-panel" aria-labelledby="verification-title"><p class="eyebrow">LIBTRACK ACCOUNT</p><h1 id="verification-title">Email verification</h1>@if(pending()){<p role="status">Checking your verification link…</p>}@else if(verified()){<div class="alert alert-success" role="status">{{message()}}</div><a class="button button-primary" routerLink="/">Continue to LibTrack</a>}@else{<div class="alert alert-error" role="alert">{{message()}}</div><a class="button button-secondary" routerLink="/">Return to LibTrack</a>}</section></main>',
})
export class VerifyEmailComponent implements OnInit {
  private readonly document = inject(DOCUMENT);
  private readonly route = inject(ActivatedRoute);
  private readonly router = inject(Router);
  private readonly auth = inject(AuthService);
  readonly pending = signal(true);
  readonly verified = signal(false);
  readonly message = signal('Checking your verification link…');

  ngOnInit(): void {
    // Capture the browser's original fragment before URL cleanup or router navigation.
    const token = verificationTokenFromLocation(
      this.route.snapshot.fragment,
      this.document.defaultView?.location.href ?? '',
    );
    if (!token) {
      this.router.navigateByUrl('/verify-email', { replaceUrl: true });
      this.pending.set(false);
      this.message.set('This verification link is missing its token.');
      return;
    }

    const verification = this.auth.verifyEmail(token);
    this.router.navigateByUrl('/verify-email', { replaceUrl: true });
    verification.pipe(finalize(() => this.pending.set(false))).subscribe({
      next: response => {
        this.verified.set(true);
        this.message.set(response.message);
      },
      error: (error: unknown) => {
        this.message.set(error instanceof HttpErrorResponse && error.status === 400
          ? 'This verification link is invalid, expired, or already used. Contact library staff for help.'
          : 'Verification could not be completed right now. Check the server connection and try again.');
      },
    });
  }
}
